#!/usr/bin/env python3
"""Convert the bundled, untransformed Poly Pizza GLB to SceneKit mesh JSON.

Standard library only; preserves all triangles, normals and material colors.
This intentionally supports only the accessor subset used by this pinned asset.
"""
import hashlib
import json
from pathlib import Path
import struct

ROOT = Path(__file__).resolve().parents[1]
DIRECTORY = ROOT / 'apps/simulator-macos/Resources/R2D2'
raw = (DIRECTORY / 'source.glb').read_bytes()
magic, version, size = struct.unpack_from('<4sII', raw)
assert (magic, version, size) == (b'glTF', 2, len(raw))
length, kind = struct.unpack_from('<II', raw, 12)
assert kind == 0x4E4F534A
model = json.loads(raw[20:20+length])
length2, kind2 = struct.unpack_from('<II', raw, 20+length)
assert kind2 == 0x004E4942
binary = raw[28+length:28+length+length2]
assert all(set(node) <= {'name', 'mesh'} for node in model['nodes'])

def accessor(index):
    a = model['accessors'][index]
    view = model['bufferViews'][a['bufferView']]
    assert view['buffer'] == 0 and 'sparse' not in a
    code = {5126: 'f', 5123: 'H'}[a['componentType']]
    count = {'VEC3': 3, 'SCALAR': 1}[a['type']]
    fmt = '<' + code*count
    stride = view.get('byteStride', struct.calcsize(fmt))
    offset = view.get('byteOffset', 0)+a.get('byteOffset', 0)
    return [struct.unpack_from(fmt, binary, offset+i*stride) for i in range(a['count'])]

parts = []
for node in model['nodes']:
    for primitive in model['meshes'][node['mesh']]['primitives']:
        assert primitive.get('mode', 4) == 4
        positions = accessor(primitive['attributes']['POSITION'])
        normals = accessor(primitive['attributes']['NORMAL'])
        # Source faces +X; simulator vehicles face +Z.
        rotate = lambda p: [-p[2], p[1], p[0]]
        parts.append(dict(positions=list(map(rotate, positions)), normals=list(map(rotate, normals)),
                          indices=[v[0] for v in accessor(primitive['indices'])],
                          color=model['materials'][primitive['material']]['pbrMetallicRoughness']['baseColorFactor']))
vertices = [v for p in parts for v in p['positions']]
low = [min(v[i] for v in vertices) for i in range(3)]
high = [max(v[i] for v in vertices) for i in range(3)]
scale = 0.85/(high[1]-low[1])
origin = [(low[0]+high[0])/2, low[1], (low[2]+high[2])/2]
for part in parts:
    part['positions'] = [[round((v[i]-origin[i])*scale, 7) for i in range(3)] for v in part['positions']]
    part['normals'] = [[round(c, 7) for c in v] for v in part['normals']]
result = dict(sourceSHA256=hashlib.sha256(raw).hexdigest(), parts=parts)
(DIRECTORY / 'mesh.json').write_text(json.dumps(result, separators=(',', ':'))+'\n')
print(f"R2-D2: {sum(len(p['indices'])//3 for p in parts)} triangles, {len(parts)} material groups")
