import AppKit
import SceneKit
import SimulationCore

/// Imported CC BY model; attribution and the original GLB ship with the app.
final class R2D2 {
    private struct Mesh: Decodable {
        struct Part: Decodable {
            let positions: [[Float]], normals: [[Float]], indices: [UInt32], color: [CGFloat]
        }
        let parts: [Part]
    }
    let root = SCNNode()
    private(set) var triangleCount = 0

    init(resources: URL) throws {
        let url = resources.appendingPathComponent("R2D2/mesh.json")
        let mesh = try JSONDecoder().decode(Mesh.self, from: Data(contentsOf: url))
        root.name = "R2-D2 · Eric Finn · CC BY 3.0"
        for part in mesh.parts {
            guard !part.positions.isEmpty, part.positions.count == part.normals.count,
                  part.positions.allSatisfy({ $0.count == 3 }), part.normals.allSatisfy({ $0.count == 3 }),
                  part.color.count == 4, part.indices.count % 3 == 0,
                  part.indices.allSatisfy({ Int($0) < part.positions.count }) else {
                throw CocoaError(.fileReadCorruptFile)
            }
            let vertices = SCNGeometrySource(vertices: part.positions.map { SCNVector3($0[0], $0[1], $0[2]) })
            let normals = SCNGeometrySource(normals: part.normals.map { SCNVector3($0[0], $0[1], $0[2]) })
            let elements = SCNGeometryElement(indices: part.indices, primitiveType: .triangles)
            let geometry = SCNGeometry(sources: [vertices, normals], elements: [elements])
            let surface = SCNMaterial()
            surface.lightingModel = .physicallyBased
            surface.diffuse.contents = NSColor(srgbRed: part.color[0], green: part.color[1], blue: part.color[2], alpha: part.color[3])
            surface.roughness.contents = 0.75
            geometry.materials = [surface]
            root.addChildNode(SCNNode(geometry: geometry))
            triangleCount += part.indices.count/3
        }
    }

    func update(_ state: Simulation) {
        root.position = SCNVector3(state.x, state.groundY, state.z)
        root.eulerAngles = SCNVector3(state.bodyPitch, state.heading, state.bodyRoll)
    }
}
